def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if len(cmd) == 0:
        return cmd

    # Fix for issue8557: https://bugs.python.org/issue8557
    # Windows does not parse shebangs, so we need to explictly
    # specify the interpreter
    if cmd[0].startswith('#!'):
        cmd = (os.environ['COMSPEC'],) + cmd

    # Fix for deep-path shebangs
    if cmd[0] != os.environ['COMSPEC']:
        cmd = (os.path.abspath(cmd[0]),) + cmd[1:]

    return cmd

