        cache = {}
        use_count = {}
        current_size = 0

        def wrapper(*args, **kwargs):
            nonlocal current_size

            if typed:
                key = repr(args) + repr(kwargs)
            else:
                key = repr(args)

            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if current_size < maxsize:
                    cache[key] = result
                    use_count[key] = 1
                    current_size += 1
                else:
                    for used_key in sorted(use_count, key=use_count.get):
                        if use_count[used_key] == 1:
                            del cache[used_key]
                            del use_count[used_key]
                            current_size -= 1
                            break
                return result

        return wrapper

    return decorator

