def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    is_valid = False
    is_oa = False
    is_ad = False
    is_u = False
    is_ua = False
    is_uo = False

    if not os.path.exists(path):
        print(f"Path does not exist: {path}")
        return is_valid

    if not os.path.isdir(path):
        print(f"Path is not a directory: {path}")
        return is_valid

    try:
        files = os.listdir(path)
    except OSError:
        print(f"Error listing directory: {path}")
        return is_valid

    for file in files:
        if file == "OCFL_object":
            is_oa = True
        if file == "OCFL_object_validation_dataset":
            is_ad = True
        if file == "OCFL_object_update_dataset":
            is_u = True
            is_ua = True
        if file == "OCFL_object_update_ora":
            is_uo = True

    # If OCFL object root directory, check for required files
    if len(files) >= 2:
        is_valid = True
        for file in files:
            if file == "OCFL_object":
                is_oa = True
            if file == "OCFL_object_validation_dataset":
                is_ad = True
            if file == "OCFL_object_update_dataset":
                is_u = True
                is_ua = True
            if file == "OCFL_object_update_ora":
                is_uo = True
            if not is_oa or not is_ad or not is_u or not is_ua or not is_uo:
                is_valid = False
                break

    # If directory is empty, it is considered valid
    if len(files) == 0:
        is_valid = True

    return is_valid

