            file_name = manifest_file.split("/")[-1]
            if file_name not in digests_used:
                raise RuntimeError(f"Digest for file {file_name} is not present in the manifest")
            if digests_used[file_name] != manifest_file:
                raise RuntimeError(f"Digest for file {file_name} is not used correctly in the manifest")
    return None

