            if algo not in manifest_files[file_path].keys():
                raise ValueError(f"Algorithm {algo} not found in manifest for {file_path}.")
    return True

def validate_fixity(self, fixity, manifest_files):
    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File {file} is not in the manifest.")
        for fixity_info in fixity[file]:
            if not isinstance(fixity_info, dict):
                raise ValueError(f"Fixity info for {file} is not in the correct format.")
            algorithm = fixity_info.get("algorithm")
            if not algorithm:
                raise ValueError(f"Fixity info for {file} does not have an algorithm specified.")
            checksum = fixity_info.get("checksum")
            if not checksum:
                raise ValueError(f"Fixity info for {file} does not have a checksum specified.")
            if not isinstance(checksum, str):
                raise ValueError(f"Fixity info for {file} has an invalid checksum.")
            expected_checksum = fixity_info.get("expected_checksum")
            if not expected_checksum:
                raise ValueError(f"Fixity info for {file} does not have an expected checksum specified.")
            if checksum != expected_checksum:
                raise ValueError(f"Fixity info for {file} has an unexpected checksum.")

