def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for i, arg in enumerate(args):
        if arg.op == '&':
            other_arg = args[i - 1]
            if other_arg.op == '|' and other_arg.args[0] == arg:
                new_args.append(arg)
            elif other_arg.op == '|' and other_arg.args[1] == arg:
                new_args.append(other_arg.args[0])
        elif arg.op == '|':
            other_arg = args[i - 1]
            if other_arg.op == '&' and other_arg.args[0] == arg:
                new_args.append(other_arg.args[1])
            elif other_arg.op == '&' and other_arg.args[1] == arg:
                new_args.append(other_arg.args[0])
        else:
            new_args.append(arg)
    return new_args

