    # Initialize variables
    root_inventory = None
    version_inventories = {}
    different_digests = set()

    # Iterate through version dirs and validate inventories
    for version_dir in version_dirs:
        # Check if version dir exists
        if not os.path.exists(version_dir):
            raise ValueError(f"Version directory '{version_dir}' does not exist")

        # Check if inventory file exists in version dir
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise ValueError(f"Inventory file '{inventory_path}' does not exist")

        # Load inventory file
        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

        # Validate inventory up to that point
        if root_inventory is None:
            root_inventory = inventory
        else:
            for key, value in inventory.items():
                if key not in root_inventory or root_inventory[key] != value:
                    different_digests.add(key)

        # Keep a record of the inventory for this version
        version_inventories[version_dir] = inventory

    # Validate that all versions have the same inventory
    if different_digests:
        raise ValueError(f"Inventories for different versions differ: {different_digests}")

    return version_inventories, root_inventory

