                msg=f"Configuration file '{config_filename}' not found",
                pathname=config_filename,
            ))
            continue
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(
                level=logging.ERROR,
                msg=f"Error parsing configuration file '{config_filename}': {e}",
                pathname=config_filename,
            ))
            continue
        else:
            configs[config_filename] = config

    if overrides:
        for key, value in overrides.items():
            for config in configs.values():
                try:
                    config[key] = value
                except KeyError:
                    pass

    if resolve_env:
        for config in configs.values():
            _resolve_env_variables(config)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = yaml.safe_load(f)
                if overrides:
                    config = _apply_overrides(config, overrides)
                if resolve_env:
                    config = _resolve_env_vars(config)
                configs[config_filename] = config
        except OSError as e:
            errors.append(logging.LogRecord(
                level=logging.ERROR,
                message=f"Error loading configuration file '{config_filename}': {e}"
            ))
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(
                level=logging.ERROR,
                message=f"Error parsing configuration file '{config_filename}': {e}"
            ))
    return configs, errors

