def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    if default is None:
        default = datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=datetime.timezone.utc)
    else:
        default = default.replace(tzinfo=datetime.timezone.utc)

    if not ignoretz:
        tzinfos = {
            "BRST": -7200,
            "CST": gettz("America/Chicago")
        }

    try:
        parts = timestr.split()
        part1, part2 = parts[0], parts[1]
        year, month, day = map(int, part1.split("-"))
        hour, minute, second = map(int, part2.split(":"))
        microsecond = 0
        if len(parts) >= 3:
            microsecond = int(parts[2])
        datetime_object = datetime.datetime(year, month, day, hour, minute, second, microsecond, datetime.timezone.utc)
        if not ignoretz:
            tzinfo = tzinfos.get(parts[3], None)
            if tzinfo is None:
                raise ParserError("Unrecognized timezone: %s" % parts[3])
            datetime_object = datetime_object.astimezone(tzinfo)
        return datetime_object
    except IndexError:
        raise ParserError("Invalid date/time string: %s" % timestr)
    except ValueError:
        raise ParserError("Invalid date/time string: %s" % timestr)
    except:
        raise

