def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if not os.path.exists(yaml_file):
        raise IRValidatorException("YAML file does not exist")

    with open(yaml_file, "r") as f:
        data = yaml.safe_load(f)

    if not data:
        raise IRValidatorException("YAML file is empty")

    if "version" not in data:
        raise IRValidatorException("'version' key is missing in YAML file")

    if "windows" not in data:
        raise IRValidatorException("'windows' key is missing in YAML file")

    for window in data["windows"]:
        if "panes" not in window:
            raise IRValidatorException("'panes' key is missing in window")
        for pane in window["panes"]:
            if "command" not in pane:
                raise IRValidatorException("'command' key is missing in pane")
            if not pane["command"]:
                raise IRValidatorException("'command' value cannot be empty")

    return data

