    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException('Failed to load YAML file {}'.format(yaml_file)) from e

    missing_keys = []
    for key, value in cls.REQUIRED_DATA.items():
        if key not in data:
            missing_keys.append(key)

    if missing_keys:
        raise IRValidatorException('The following required keys are missing in the YAML file: {}'.format(
            ', '.join(missing_keys)))

    return data

